CREATE TABLE material_preparations ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, connection_id TEXT NOT NULL, snapshot TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','pause_requested','cancel_requested','paused','cancelled','completed','uncertain','stale')), step_id TEXT NOT NULL, indexed INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL DEFAULT 0, detail TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE UNIQUE INDEX material_preparation_active ON material_preparations(project_id) WHERE status IN ('queued','running','pause_requested','cancel_requested','paused','uncertain');
CREATE INDEX material_preparation_recovery ON material_preparations(status,updated_at);
